              <Select key={`decide-${d.id}`} options={d.options.map(o => ({ value: o, label: o }))} onSelect={(value: string) => void answerDecision($, d.id, value)} />
            </Box>
          ) : (
            row(i ? '' : 'Decide', `${d.id} ${d.question} (answer in the prompt)`, 'warning')
