const NAV = [
  ['goal', 'Goal'],
  ['workflow', 'Workflow'],
  ['design', 'Design'],
  ['acceptance', 'Acceptance'],
  ['release', 'Release'],
  ['phases', 'Phases'],
  ['matrix', 'Traceability'],
  ['tasks', 'Tasks'],
  ['drift', 'Drift'],
  ['runlog', 'Run log'],
  ['docs', 'Documents'],
]

const FOOTER = 'This page is local and is regenerated after every step. It holds your own words: keep it out of commits and do not share it.'

/** The whole dashboard as one HTML document: deterministic for the same input, nothing loaded from outside. */
export function renderDashboard(input: DashboardInput): string {
  const refresh = Number(input.refreshSeconds)
  const auto = Number.isFinite(refresh) && refresh > 0
  return [
    '<!doctype html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${esc(input.snap.spec?.title ?? 'Spec X-Ref')} · Spec X-Ref</title>`,
    `<style>${CSS}</style>`,
    '</head>',
    '<body>',
    header(input),
    `<nav>${NAV.filter(([id]) => (id !== 'design' || input.design) && (id !== 'acceptance' || (input.snap.ui && scenariosOf(input.snap.spec).length)) && (id !== 'release' || input.snap.release)).map(([id, label]) => `<a href="#${id}">${label}</a>`).join('')}</nav>`,
    '<main>',
    goal(input),
    workflow(input),
    design(input),
    acceptance(input),
    release(input),
    phases(input),
    matrix(input),
    tasks(input),
    drift(input),
    runLog(input),
    docs(input),
    '</main>',
    `<footer><p>${FOOTER}</p>${auto ? `<p>Refreshes every ${Math.floor(refresh)} s; it waits while you select text or the tab is hidden.</p>` : ''}</footer>`,
    auto ? refreshScript(refresh) : '',
    '</body>',
    '</html>',
    '',
  ].join('\n')
}

