// The design pass (0.9.0): a done feature that works and was tried is lifted to the look and feel of its platform's best
// apps, on the person's word. A design lead sets the direction and builds two or three sample screens, the person
// approves it at the samples, the implementer builds the rest, and the design lead reviews fresh screenshots of every
// screen (three rounds at most). Pure: workflow.ts hands the steps over, register.tsx reads polish.md.

import type { PolishNote, Snapshot, Task } from '../types'
import { tryTools } from './orchestrate'
import { fingerprint } from './rules'

export const polishDoc = (featureDir: string) => `${featureDir}/polish.md`
/** The phases a design pass writes. Not "Polish": Spec Kit's own tasks end with "Polish & Cross-Cutting Concerns". */
export const DESIGN_PHASE = /^Phase\s+\d+:\s*Design (pass|review)\b/i
export const isDesignPhase = (phase: string | null | undefined) => !!phase && DESIGN_PHASE.test(phase)
/** Review rounds of a design pass before it counts as done. */
export const MAX_DESIGN_REVIEWS = 3

/** The review rounds so far: one `Design review N` phase per round that found something. */
export const designRounds = (tasks: Task[]) => new Set(tasks.filter(t => /^Phase\s+\d+:\s*Design review\b/i.test(t.phase)).map(t => t.phase)).size

/** polish.md as the mod reads it: the direction's first line, and the fingerprint the person approves (the rounds aside). */
export function parsePolish(md: string): PolishNote {
  const head = md.split(/^##\s+Rounds\b/m)[0]!
  const lines = head.split('\n')
  const at = lines.findIndex(l => /^##\s+Direction\b/i.test(l))
  const direction = at >= 0 ? (lines.slice(at + 1).find(l => l.trim() && !l.startsWith('#'))?.trim() ?? null) : null
  return { direction, fingerprint: fingerprint(head.trim()), rounds: (md.match(/^###\s+Round\s+\d+/gm) ?? []).length }
}

/** What the best apps of each platform look and feel like today, by their conventions rather than by version. */
export const PLATFORM_LOOK = [
  'iOS: content runs edge to edge, and navigation and controls sit on translucent material that floats above it (tab bar, toolbars, floating buttons), not on opaque bars; large titles that collapse as the content scrolls; sheets with detents for secondary tasks instead of full screens; system symbols (SF Symbols) with or instead of text; Dynamic Type text styles, no fixed font sizes; semantic system colours and materials that follow light and dark mode; haptics when something is committed (saved, liked, done); springy, interruptible motion; native controls (segmented control, menu, picker, switch) over home-made ones; swipe actions and context menus where a list invites them; empty, loading and error states designed, not left to defaults.',
  'Android: Material 3 in its expressive form: dynamic colour, large shapes, motion that carries meaning, edge to edge, predictive back.',
  'Web: the same direction in CSS: backdrop-filter materials, the system font stack, prefers-color-scheme and prefers-reduced-motion, a visible focus ring.',
  'Always: one clear primary action per screen, touch targets of at least 44 pt, contrast AA, labels for VoiceOver and TalkBack, Reduce Motion and Reduce Transparency honoured.',
].join('\n')

/** How to build it: the platform's own parts, the skills that know them, and what stays out of the step. */
export const DESIGN_TOOLS =
  "Build with the platform's own components first: for Expo the expo-ui, expo-native-ui, expo-router and expo-animation skills where they are installed (native controls, materials and blur, native stack and tabs, motion); for Flutter Cupertino and Material 3; for SwiftUI the system materials and controls. Adding a package of the app's framework is fine (with the project's package manager, e.g. `npx expo install`); a change that needs a new native build (a development build, pods) becomes a task of its own with the reason, never part of this step."

/** The design lead's system prompt: the look rises, what the app does stays. */
export const DESIGNER_PROMPT = [
  'You are the design lead for an app that works and that people have tried: you lift its look and feel to the level of the best apps on its platform, without changing what it does. The speckit-xref autopilot delegates to you; your prompt says whether you set the direction or review a built design pass.',
  `What "best" means here:\n${PLATFORM_LOOK}`,
  DESIGN_TOOLS,
  'What the app does stays: the same screens, flows and the texts that carry meaning, and every test green (run the test command after each change). A test that checks only the old look may follow the new one.',
  'Only what you saw on this build counts: a "before" shot may come from the user test (specs/<feature>/try/), every "after" shot is taken now.',
  'Before each task call mcp__speckit-xref__focus with its id; a file no task names gets mcp__speckit-xref__link to the task it serves.',
  'End with a report of at most eight lines.',
].join('\n\n')

/** The design lead's first step: the direction, the tasks, two or three sample screens. The rest waits for the person. */
export function directionBrief(snap: Snapshot): string {
  const dir = snap.featureDir ?? 'specs/<feature>'
  const screens = (snap.design?.screens ?? []).map(s => s.name)
  return [
    `Set the design direction for ${dir}: the app works and was tried; now it should look and feel like the best apps on its platform. Time box: about 30 minutes.`,
    ...(screens.length ? [`Screens: ${screens.join(', ')}.`] : []),
    tryTools(snap),
    `1. Use the app and take a "before" shot of every screen, light and dark, under ${dir}/polish/before/ (a shot of this build from ${dir}/try/ will do).`,
    `2. Write ${dir}/polish.md: \`## Direction\` (its first line says the feel in one sentence; then the materials, type, colour, symbols, motion and haptics, and what stays), \`## Screens\` (per screen: what changes and with which native components), \`## Samples\` (filled in at step 4), \`## Rounds\` (empty; the reviews add to it). Bring DESIGN.md to the new direction, in its own format.`,
    `3. Before any code, append \`## Phase N: Design pass\` to ${dir}/tasks.md (the next phase number, the next free T### ids): first one task for the shared parts (theme, type, components, navigation), then one task per screen, each with its files in backticks and the story it serves.`,
    `4. Build the shared task and two or three screens that show the direction best, as samples, each under its task; check those tasks off once the tests pass. Take an "after" shot of each sample under ${dir}/polish/after/ and list before → after per sample under \`## Samples\`.`,
    '5. Leave the other screens\' tasks open: the person approves the direction at the samples first.',
    'Start servers, simulators and browsers in the background and stop the ones you started at the end.',
  ].join('\n')
}

/** The design lead's review of a built pass: fresh shots of every screen against the direction. */
export function critiqueBrief(snap: Snapshot, round: number): string {
  const dir = snap.featureDir ?? 'specs/<feature>'
  return [
    `Review round ${round} of ${MAX_DESIGN_REVIEWS}: is the built design pass of ${dir} what polish.md promises, on this build? Time box: about 20 minutes. Change no code in this step.`,
    tryTools(snap),
    `Take a fresh shot of every screen, light and dark, under ${dir}/polish/round-${round}/, and compare each with polish.md (direction and screen plan), DESIGN.md and the platform's conventions.`,
    'Rate each finding: HIGH (a screen still looks as before, or the new look breaks something: text cut off, contrast below AA, a control hidden under material, a flow that no longer works), MEDIUM (a deviation from the direction a person notices: spacing, alignment, an inconsistent component, a missing state), LOW (taste).',
    `Each HIGH or MEDIUM finding becomes a task under \`## Phase N: Design review ${round}\` in ${dir}/tasks.md (the next phase number and free T### ids, the screen, what to change, its files in backticks). Add \`### Round ${round}\` under \`## Rounds\` in polish.md: the date, per screen OK or its findings, the shot paths; LOW findings stay there.`,
    'Without a way to tap (no simulator tool, no Maestro) say which screens you only looked at and did not use. No HIGH or MEDIUM finding: say so; the design pass is then done.',
    'Start servers, simulators and browsers in the background and stop the ones you started at the end.',
  ].join('\n')
}

/** What an implement step of a design pass adds to its brief. */
export const DESIGN_PASS_RULES = [
  'This phase is a design pass: change how the app looks and feels, not what it does. Follow polish.md (direction, screen plan, samples) and DESIGN.md, and reuse the shared parts the samples introduced.',
  DESIGN_TOOLS,
  'Keep every test green; a test that checks only the old look may follow the new one. Take an "after" shot of each screen you finish, under the feature\'s polish/after/.',
].join('\n')

files.hooks/gitci.ts:
// Tests, CI/CD and git (0.11.0): what a project builds besides the app, and where its work lands. A proof of concept or
// an MVP needs a type check and a person trying the app, not a test suite or a pipeline the agents spend their time on;
// and a feature lands on the branch the person works on unless they ask for a branch or a pull request. Pure.

import type { Ledger, Snapshot } from '../types'

export type TestMode = 'off' | 'run' | 'lean'
export type GitMode = 'current' | 'branch' | 'pr'
export const TEST_MODES: TestMode[] = ['off', 'run', 'lean']
export const GIT_MODES: GitMode[] = ['current', 'branch', 'pr']

/** CI/CD pipelines: written only when the person switches option ci on. */
export const CI_PATH = /(^|\/)(\.github\/workflows\/|\.gitlab-ci\.ya?ml$|\.circleci\/|bitbucket-pipelines\.ya?ml$|azure-pipelines\.ya?ml$|\.eas\/workflows\/|Jenkinsfile$|\.buildkite\/|\.travis\.ya?ml$|codemagic\.ya?ml$|fastlane\/)/
/** The same paths inside a shell command, after a space, a quote or a slash. */
const CI_IN_COMMAND = new RegExp(CI_PATH.source.replace('(^|\\/)', '(^|[\\s/\'"=])').replace(/\$/g, '(?![\\w.-])'))
const WRITES = /(>|\btee\b|\bcp\b|\bmv\b|\bmkdir\b|\btouch\b|\bln\b|\binstall\b|\b(?:sed|perl)\s+(?:-[a-zA-Z]*\s+)*-i\b)/

/** Whether a call writes a CI/CD pipeline: a file tool on one, or a shell command that names one and writes. */
export function touchesCi(tool: string, input: Record<string, unknown>, root = ''): boolean {
  const rel = (p: string) => (root && p.startsWith(root + '/') ? p.slice(root.length + 1) : p)
  if (tool === 'Write' || tool === 'Edit' || tool === 'NotebookEdit') return CI_PATH.test(rel(String(input.file_path ?? input.notebook_path ?? '')))
  if (tool !== 'Bash') return false
  const command = String(input.command ?? '')
  return CI_IN_COMMAND.test(command) && WRITES.test(command)
}

/** A git command that makes or changes branches: the run stays on the person's branch unless option git says otherwise. */
const BRANCHING = /\bgit\s+(?:-C\s+\S+\s+)?(switch\b|checkout\s+(?:-[bB]|--orphan)\b|branch\s+(?!-)[^\s;&|]+|worktree\s+add\b)/
export const branches = (tool: string, input: Record<string, unknown>) => tool === 'Bash' && BRANCHING.test(String(input.command ?? ''))

/** A feature's branch: its folder's name, as Spec Kit numbers it. */
export const branchName = (featureDir: string) => featureDir.slice(featureDir.lastIndexOf('/') + 1)

/** What the steps that plan or build are told about tests. */
export function testsNote(mode: TestMode | undefined): string | null {
  if (mode === 'off') return 'Write no test tasks and no tests: this project runs without a test suite (option tests: off). The type check and the user test are its checks.'
  if (mode === 'run') return 'Write no new tests or test tasks (option tests: run): the existing suite is the gate; keep it green.'
  return null
}

/** What the steps are told about CI/CD. */
export const ciNote = (on: boolean | undefined) => (on === false ? 'Plan and write no CI/CD pipeline (no workflow files): option ci is off, and writing one is refused.' : null)

/** What the autopilot's gate is called: the project's tests, or its type check where it runs without tests. */
export function gateWords(snap: Pick<Snapshot, 'gate'>): { what: string; fails: string; still: string; passes: string; label: string } {
  return snap.gate === 'check'
    ? { what: 'the type check', fails: 'The type check fails', still: 'The type check still fails', passes: 'the type check passes', label: 'Check' }
    : { what: 'the tests', fails: 'The tests fail', still: 'The tests still fail', passes: 'the tests pass', label: 'Tests' }
}

/** What the project shows of its language: enough to name its type check. */
export type Project = {
  packageJson: string | null
  typescript: boolean
  pubspec: string | null
  cargo: boolean
  goMod: boolean
  swiftPackage: boolean
  mypy: boolean
  /** The package manager's run command: `npm run`, `pnpm`, `yarn`, `bun run`. */
  run: string
}

/** The type check of the project's language, or null: a script of its own first, else the language's usual one. */
export function checkCommandFor(p: Project): string | null {
  if (p.packageJson) {
    let scripts: Record<string, unknown> = {}
    try {
      scripts = (JSON.parse(p.packageJson) as { scripts?: Record<string, unknown> }).scripts ?? {}
    } catch {
      scripts = {}
    }
    const own = ['typecheck', 'type-check', 'check-types', 'types', 'tsc'].find(s => typeof scripts[s] === 'string')
    if (own) return `${p.run} ${own}`
  }
  if (p.typescript) return 'npx --no-install tsc --noEmit'
  if (p.pubspec) return /^\s*flutter\s*:/m.test(p.pubspec) ? 'flutter analyze --no-fatal-infos' : 'dart analyze'
  if (p.cargo) return 'cargo check'
  if (p.goMod) return 'go vet ./...'
  if (p.swiftPackage) return 'swift build'
  if (p.mypy) return 'mypy .'
  return null
}

/** The pull request's text: what the feature is, what it covers, how it was checked. */
export function prBody(snap: Snapshot, ledger: Ledger): string {
  const spec = snap.spec
  const done = snap.tasks.filter(t => t.done).length
  const reqs = (spec?.reqs ?? []).filter(r => r.kind === 'FR' && r.status === 'active').slice(0, 20)
  const checked = [
    ledger.checkpoints.verify ? 'verified against the spec' : null,
    ledger.checkpoints.try ? 'tried as a person would (user test)' : null,
    snap.gate === 'check' ? 'type check green' : 'tests green',
  ].filter(Boolean)
  return [
    `## ${spec?.title ?? branchName(snap.featureDir ?? '')}`,
    '',
    spec?.input ? `> ${spec.input.replace(/\s+/g, ' ').slice(0, 600)}` : '',
    '',
    `Spec: \`${snap.featureDir}/spec.md\` · Tasks: ${done}/${snap.tasks.length} · ${checked.join(' · ')}`,
    '',
    ...(reqs.length ? ['### Requirements', ...reqs.map(r => `- **${r.id}** ${r.text.slice(0, 200)}`), ''] : []),
    'Built with GitHub Spec Kit and the speckit-xref autopilot. Merging is yours.',
  ]
    .filter((l, i, all) => l !== '' || all[i - 1] !== '')
    .join('\n')
}

files.hooks/deputy.ts:
// The deputy (0.10.0): the autopilot thinks between its steps the way the person would. After each heavy step it
// reviews the work like a lead who reads the report and the diff (go on, send it back with a list, or ask the person),
// it answers the questions Claude asks from the spec, the briefs and the person's own earlier words, and it says what
// it decided and why. The workflow stays the frame; the deputy never approves a gate. Pure: register.tsx calls it.

import type { Snapshot, Task } from '../types'

/** The person's profile, learned from their own words only: local, like their prompts, never committed. */
export const PROFILE = '.specify/xref/local/person.md'
/** The steps whose work the deputy reviews: the ones that build, repair, try or restyle the app. */
export const REVIEWED = new Set(['implement', 'repair', 'rework', 'try', 'polish', 'bug'])
/** Send-backs of one step before it becomes the person's call. */
export const MAX_REWORKS = 2

export type Verdict = {
  verdict: 'go' | 'rework' | 'ask' | 'redirect'
  /** The next step the deputy writes itself when the plan no longer fits (redirect, 0.12.0). */
  prompt: string
  /** For the next step: what to watch, in a line or two; empty when there is nothing to say. */
  note: string
  /** What the step has to fix before it counts (rework). */
  rework: string[]
  /** The person's question and the deputy's recommendation (ask). */
  question: string
  recommendation: string
  /** What the person said that is worth keeping about how they work (from their own words only). */
  profile: string[]
}

export type Answer = { decided: true; answer: string; why: string } | { decided: false; question: string; recommendation: string }

/** What only the person decides, whatever the deputy thinks: checked in code, not left to the prompt. */
const PERSON_ONLY = /\b(passwords?|credentials?|api[- ]keys?|secrets?|payments?|purchases?|billing|subscriptions?|wipe|force[- ]push|publish(ing)?|releases?|deploy(ing|ment)?|approv\w*|real (users?|devices?|data)|measur\w*|by hand|manually|passw(ort|örter)|zugangsdaten|api-schlüssel|zahlung\w*|bezahl\w*|kauf\w*|abonnement\w*|lösch\w*|veröffentlich\w*|freigabe\w*|freigeben|messung\w*|messen|von hand|manuell\w*|echte[nrs]? (nutzer\w*|geräte?\w*|daten)|smoke[- ]?tests?|simulator|emulator|on (a|the) (real )?device|check(ed)? by hand)\b|\b(delete|drop)\b/i

/** A question the deputy may not answer for the person, whatever the model says. */
export const personOnly = (question: string) => PERSON_ONLY.test(question)

/** The deputy's system prompt: the person's stand-in, with the person's limits. */
export const DEPUTY_PROMPT = [
  'You stand in for the person who owns this product while an autopilot builds it with GitHub Spec Kit. You are their deputy between the steps: you read what each step did the way they would, critically and with their goals in mind, and you decide what they would decide. You are thorough, not quick: read the report, the diff and the test run before you judge.',
  'Your sources, in this order: the person\'s own words and earlier decisions, their profile, the spec and its requirements, the constitution, the plan. Where they settle a question, decide it; where they do not, decide what serves the spec and record it, unless the question is one only the person can answer.',
  'Only the person decides: approvals of the spec, the plan, a design direction or a release; anything that costs money, needs credentials or an account, deletes or publishes something, or cannot be undone; a check by hand or a measurement on real users, data or devices; a matter of taste where the person never gave a direction; a conflict between their words and the spec.',
  'Answer with one JSON object and nothing else.',
].join('\n\n')

/** What a step review sees: what was asked, what came back, what changed, whether it holds. */
export type ReviewInput = {
  feature: string
  phase: string
  why: string
  /** The step's report: the subagent's whole report where it ran in one, else the session's answer. */
  report: string
  /** Every file changed since the step started, from git: the diff may be cut, this list is whole. */
  files: string[]
  diff: string
  tests: { ok: boolean; output: string } | null
  checked: string[]
  open: string[]
  requirements: string[]
  profile: string | null
  /** The person's own recent words and decisions, newest last. */
  words: string[]
  decisions: string[]
  principles: string[]
  /** The step finished a phase or the feature: look ahead too. */
  boundary: boolean
  reworks: number
  /** Option tests (0.11.0): without a suite a missing test is no reason to send a step back. */
  testMode?: 'off' | 'run' | 'lean'
}

const section = (title: string, lines: string[] | string | null) => {
  const body = Array.isArray(lines) ? lines.filter(Boolean).join('\n') : (lines ?? '').trim()
  return body ? `## ${title}\n${body}` : ''
}

/** The review request: the evidence, then the questions a lead asks, then the answer's shape. */
export function reviewRequest(i: ReviewInput): string {
  return [
    `Feature ${i.feature}. The step just done: ${i.phase} (${i.why}).${i.reworks ? ` It was sent back ${i.reworks} time${i.reworks === 1 ? '' : 's'} already.` : ''}`,
    section('Report of the step', i.report.slice(-8000)),
    section('Files changed since the step started (from git; the diff below may be cut, this list is whole)', i.files.slice(0, 80)),
    section('Diff of the step', i.diff),
    section('Test run', i.tests ? `${i.tests.ok ? 'passed' : 'FAILED'}\n${i.tests.output.slice(-1500)}` : 'not run'),
    section('Tasks checked in this step', i.checked.join(', ') || 'none'),
    section('Tasks still open', i.open.slice(0, 12)),
    section('Requirements these tasks serve', i.requirements.slice(0, 20)),
    section("The person's profile", i.profile),
    section("The person's own words, newest last", i.words.slice(-8)),
    section('Decisions so far', i.decisions.slice(-8)),
    section('Constitution', i.principles.slice(0, 12)),
    [
      '## Judge it as the person would',
      '- Does the work do what the tasks and requirements say, or does the report claim more than the diff and the test run show?',
      '- Evidence: is anything checked off on results written earlier, on a test that was weakened or skipped, or on "should work"? A check by hand or a measurement counts only when done now; one no tool here can do is the person\'s part and stays open, which is no reason to send the step back.',
      '- Scope: work no task asked for, a decision taken that the spec or the person left open, a deviation from the plan or a contract, a TODO or a stub left behind.',
      '- Anything the report says is left open or unsure: is that fine to carry on with, or does it block?',
      '- A file the report names that is in the file list but not in the diff was cut from the diff for length: that is no reason to send the step back. Send a step back only for what the evidence shows is missing or wrong.',
      ...(i.testMode === 'off' ? ['- This project runs without a test suite on purpose (option tests: off): the type check is its gate. A missing test is no reason to send a step back; a test written anyway is work nobody asked for.'] : i.testMode === 'run' ? ['- This project adds no new tests (option tests: run): the existing suite is the gate. A missing new test is no reason to send a step back.'] : []),
      ...(i.boundary ? ['- This step ended a phase or the feature: are we still building the right thing? Does anything the step or a user test found change what should come next, or need the person?'] : []),
      '',
      'verdict "go": the step holds; "note" is what the next step should keep in mind (empty if nothing). verdict "rework": it does not hold; "rework" lists what to fix, concretely, each with the file or task. verdict "ask": only the person can settle what blocks; "question" asks it in one or two sentences, "recommendation" says what you would choose and why. verdict "redirect": the step holds, but what it found means the plan no longer fits (a task belongs to a later feature, an order that cannot work, a prerequisite missing): "prompt" is the next step written by you for Claude, concrete and complete, and the plan goes on from what it leaves; mark a task put off as deferred in tasks.md with [~] and the reason.',
      '"profile": at most three short lines about how the person works or what they want, only where their own words above show it and the profile does not say it yet; else [].',
      'Answer: {"verdict": "go|rework|ask|redirect", "note": "", "rework": [], "question": "", "recommendation": "", "prompt": "", "profile": []}',
    ].join('\n'),
  ]
    .filter(Boolean)
    .join('\n\n')
}

/** What an answer to Claude's question sees. */
export type AnswerInput = {
  feature: string
  question: string
  /** The answer it ends, or the agent's context for the ask. */
  context: string
  options: string[]
  spec: string[]
  profile: string | null
  words: string[]
  decisions: string[]
  principles: string[]
  brief: string | null
}

export function answerRequest(i: AnswerInput): string {
  return [
    `Feature ${i.feature}. Claude asks the person, mid-run: "${i.question}"${i.options.length ? ` Options: ${i.options.join(' | ')}.` : ''}`,
    section('What Claude said before the question', i.context.slice(-3000)),
    section('Spec (requirements and assumptions)', i.spec.slice(0, 40)),
    section('Product brief', i.brief),
    section("The person's profile", i.profile),
    section("The person's own words, newest last", i.words.slice(-8)),
    section('Decisions so far', i.decisions.slice(-8)),
    section('Constitution', i.principles.slice(0, 12)),
    [
      '## Answer it as the person would',
      'Decide it yourself where the sources settle it or a sound default serves the spec; say why in one sentence, naming the source. Leave it to the person only where it is theirs alone (see your instructions), and then say what you would recommend.',
      'A question that only asks whether to go on is answered "yes, go on".',
      'Answer: {"decided": true, "answer": "", "why": ""} or {"decided": false, "question": "", "recommendation": ""}',
    ].join('\n'),
  ]
    .filter(Boolean)
    .join('\n\n')
}

/** The first JSON object in a reply, or null. */
function jsonOf(text: string): Record<string, unknown> | null {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  try {
    const value = JSON.parse(text.slice(start, end + 1))
    return value && typeof value === 'object' ? (value as Record<string, unknown>) : null
  } catch {
    return null
  }
}
const strOf = (v: unknown, max = 600) => (typeof v === 'string' ? v.trim().slice(0, max) : '')
const listOf = (v: unknown, n: number, max = 300) => (Array.isArray(v) ? v.map(x => strOf(x, max)).filter(Boolean).slice(0, n) : [])

/** The review's verdict, or null when the reply is none (the autopilot then goes on as without a deputy). */
export function parseVerdict(text: string): Verdict | null {
  const j = jsonOf(text)
  if (!j || !['go', 'rework', 'ask', 'redirect'].includes(String(j.verdict))) return null
  const v: Verdict = {
    verdict: j.verdict as Verdict['verdict'],
    prompt: strOf(j.prompt, 3000),
    note: strOf(j.note, 400),
    rework: listOf(j.rework, 8),
    question: strOf(j.question, 400),
    recommendation: strOf(j.recommendation, 400),
    profile: listOf(j.profile, 3, 160),
  }
  // A send-back without a list, or a question without one, is no verdict to act on.
  if (v.verdict === 'rework' && !v.rework.length) return { ...v, verdict: 'go' }
  if (v.verdict === 'ask' && !v.question) return { ...v, verdict: 'go' }
  if (v.verdict === 'redirect' && !v.prompt) return { ...v, verdict: 'go' }
  return v
}

/** What the deputy reads after the person spoke in the middle of the run (0.12.0). */
export type SteerInput = {
  feature: string
  /** The person's words, and Claude's answer to them. */
  words: string
  answer: string
  /** The step the plan would hand over next: its kind and why, and whether only the person can take it. */
  planned: string
  open: string[]
  deferred: string[]
  profile: string | null
  decisions: string[]
}

export type Steer = { action: 'plan' | 'custom' | 'pause'; note: string; prompt: string; question: string }

/** The steering request: the person's words first, the plan second. */
export function steerRequest(i: SteerInput): string {
  return [
    `Feature ${i.feature}. The person spoke to Claude in the middle of the autopilot's run.`,
    section("The person's words", i.words.slice(-3000)),
    section("Claude's answer to them", i.answer.slice(-4000)),
    section("The autopilot's planned next step", i.planned),
    section('Tasks still open', i.open.slice(0, 15)),
    section('Tasks the person put off', i.deferred.slice(0, 15)),
    section("The person's profile", i.profile),
    section('Decisions so far', i.decisions.slice(-8)),
    [
      "## Decide what comes next, as the person's deputy",
      'The person\'s words come before the plan. The plan is a means: follow it where the person\'s words leave it standing, change it where they changed course.',
      '- "plan": the words leave the plan as it is (a remark, a question Claude answered, something Claude already did in its answer). The planned step follows; "note" is what it should keep in mind.',
      '- "custom": the person changed course and it is not done yet (close or skip something, put tasks off, reorder, a different next feature, do something first). Write the next step yourself in "prompt", concrete and complete, for Claude to carry out what the person asked. Tasks the person put off are marked deferred in tasks.md with [~] and the reason. The plan goes on from the state it leaves.',
      '- "pause": the person wants to take over, stop, or decide something first; "question" says what the run waits for.',
      'A step you write never approves the spec, the plan, a design or a release, never deploys or pushes, and never undoes the person\'s work.',
      'Answer: {"action": "plan|custom|pause", "note": "", "prompt": "", "question": ""}',
    ].join('\n'),
  ]
    .filter(Boolean)
    .join('\n\n')
}

/** The steering answer, or null when the reply is none (the run then goes on as without a deputy). */
export function parseSteer(text: string): Steer | null {
  const j = jsonOf(text)
  if (!j || !['plan', 'custom', 'pause'].includes(String(j.action))) return null
  const s: Steer = { action: j.action as Steer['action'], note: strOf(j.note, 400), prompt: strOf(j.prompt, 3000), question: strOf(j.question, 400) }
  if (s.action === 'custom' && !s.prompt) return { ...s, action: 'plan' }
  if (s.action === 'pause' && !s.question) return { ...s, question: 'the person wants to decide how to go on' }
  return s
}

/** The step a person's change of course becomes: the deputy's prompt, with the person's words beside it. */
export const steerLine = (words: string) => `The person said, mid-run: "${words.replace(/\s+/g, ' ').slice(0, 300)}". Their words come before the plan.`

/** The answer to a question, or null when the reply is none. What only the person decides stays theirs, in code. */
export function parseAnswer(text: string, question: string): Answer | null {
  const j = jsonOf(text)
  if (!j || typeof j.decided !== 'boolean') return null
  if (j.decided && strOf(j.answer) && !personOnly(question)) return { decided: true, answer: strOf(j.answer, 500), why: strOf(j.why, 300) }
  return { decided: false, question: strOf(j.question, 400) || question, recommendation: strOf(j.recommendation, 400) }
}

/** The send-back's brief: the step again, with the deputy's list first. */
export function reworkBrief(feature: string, phase: string, items: string[], report: string): string {
  return [
    `Feature: ${feature}. The person's deputy reviewed the last ${phase} step and sends it back. Fix these, then run the tests:`,
    ...items.map(x => `- ${x}`),
    'Uncheck a task in tasks.md whose work is not done after all; check nothing new off. A point you cannot fix here (no tool, a decision only the person can make) stays open: say so in your report.',
    `The step's report was:\n${report.slice(-1500)}`,
  ].join('\n')
}

/** The note the next step carries: the deputy's word on the last one. */
export const noteLine = (note: string) => `The person's deputy on the last step: ${note}`

/** What the deputy decided, as the next step reads it. */
export const answerLine = (question: string, answer: string, why: string) => `The person's deputy answered your question "${question.slice(0, 200)}": ${answer}${why ? ` (${why})` : ''}. Go on with it.`

/** The requirements a step's tasks serve, as the review reads them. */
export function requirementsOf(snap: Snapshot, tasks: Task[]): string[] {
  const ids = new Set(tasks.flatMap(t => t.reqs))
  return (snap.spec?.reqs ?? []).filter(r => ids.has(r.id)).map(r => `${r.id}: ${r.text}`)
}

/** Lines of the profile to add: new ones only. */
export function profileAdditions(current: string | null, lines: string[]): string[] {
  const have = (current ?? '').toLowerCase()
  return lines.filter(l => l && !have.includes(l.toLowerCase()))
}

