// Where a project stands in Spec Kit's workflow, the step that comes next, and the autopilot's rules. Pure: register.tsx hands in the snapshot.

import type { Autopilot, IdeaBrief, Ledger, NextWork, Snapshot, Task } from '../types'
import { acceptPrompt, scenariosOf } from './accept'
import { bugPrompt, changePrompt, doneAsk, phaseBrief, runbookNote, verifyKey } from './brief'
import { PRD, PRD_NOTE, PRD_PROMPT, PRD_SHAPE_PROMPT, prdCoverage, roadmapItemOf, roadmapSpecify } from './prd'
import { designChangeLine, designDue, designNote, designPrompt, designToReview } from './design'
import { RELEASE, releaseBlockers, releaseLine, releasePrompt, releaseRuns, shipPrompt } from './ship'
import { DESIGNER, IMPLEMENTER, TESTER, TESTER_PROMPT, implementBrief, relayPrompt, repairBrief, routeModel, tryBrief } from './orchestrate'
import { DESIGNER_PROMPT, DESIGN_PASS_RULES, MAX_DESIGN_REVIEWS, critiqueBrief, designRounds, directionBrief, isDesignPhase } from './polish'
import { ciNote, gateWords, testsNote } from './gitci'
import type { Delegate, Models } from './orchestrate'
import { fingerprint, specFingerprint } from './rules'
import { evaluate, speckitCommand } from './xref'

export type Phase =
  | 'setup'
  | 'integration'
  | 'prd'
  | 'validate'
  | 'shape'
  | 'constitution'
  | 'specify'
  | 'clarify'
  | 'review'
  | 'plan'
  | 'design'
  | 'tasks'
  | 'revise'
  | 'map'
  | 'analyze'
  | 'remediate'
  | 'checklists'
  | 'implement'
  | 'repair'
  | 'rework'
  | 'adjust'
  | 'converge'
  | 'verify'
  | 'accept'
  | 'try'
  | 'polish'
  | 'bug'
  | 'ship'
  | 'release'
  | 'done'
export type Step = {
  phase: Phase
  command: string | null
  why: string
  notes: string[]
  /** Set when only the person can take this step: what they have to do. */
  needsUser: string | null
  /** What the step hands Claude instead of "run <command>", for steps that are no single command. */
  prompt?: string
  /**
   * What the step settles: an approval only the person gives (`spec`, `plan`, `checklists`), or a checkpoint the
   * autopilot records when it hands the step over (`analyze`, `converge`); the value is the fingerprint it holds for.
   */
  approve?: { key: string; value: string }
  /** The request a revise step folds into the spec: handing the step over takes it off the list. */
  resolves?: string
  /** The step carries out what the person said comes after a done feature: handing it over takes that off the list. */
  consumes?: boolean
  /** The step runs in a subagent the main session relays to: its agent type, model and brief (0.8.0). */
  delegate?: Delegate
}

/** Where the autopilot stops for the person: the spec always (unless none), the plan and the design when named. */
export type Review = 'spec' | 'spec+plan' | 'spec+design' | 'spec+plan+design' | 'none'
export const REVIEWS: Review[] = ['spec+design', 'spec', 'spec+plan', 'spec+plan+design', 'none']
export const gatesOf = (review: Review) => ({ spec: review !== 'none', plan: review.includes('plan'), design: review.includes('design') })

/** What the workflow reads beyond the snapshot: the review option, the persistence model, the last test run. */
export type Flow = {
  review: Review
  /** Validate and Shape for a new project's first feature (both on unless switched off). */
  validate?: boolean
  shape?: boolean
  /** The design step for a feature with a user interface (on unless switched off). */
  design?: boolean
  /** After a done feature: what comes next in the person's words, or the kind they chose before saying it. */
  next?: NextWork | null
  nextKind?: NextWork['kind'] | null
  /** The verify steps handed over in this run. */
  verifies?: number
  /** The acceptance step for a feature with a user interface (on unless switched off). */
  acceptance?: boolean
  /** Heavy steps (implement, repair, user test) run in subagents, with a model per step (0.8.0; off unless on). */
  orchestrate?: boolean
  models?: Models
  /** The user test: each story tried as a person would right after it is built, and the whole app before done (off unless on). */
  userTest?: boolean
  lastTest?: Autopilot['lastTest']
  repairs?: number
  /** The last analysis found something to fix: the next step applies its remediation. */
  remediate?: boolean
}

const INIT = 'init --here --force --non-interactive --integration claude'
export const MAX_REPAIRS = 3
/** Verify rounds in one run before closing the feature becomes the person's call: verify can always find one more thing. */
export const MAX_VERIFIES = 2
/** With acceptance each round is verify and accept, and a failing scenario gets its fixes: three rounds. */
export const MAX_ACCEPTS = 3

/** How a verification sorts what it finds: only what matters becomes work. */
export const VERIFY_RULE = [
  "Rate each finding: HIGH (a requirement, a scenario or a point of the person's words is not met), MEDIUM (it is met only in part, or no test proves it), LOW (polish, wording, an anchor or a comment, a nice-to-have).",
  "Only HIGH and MEDIUM findings become tasks; name the LOW ones in your answer under 'Low, no task'. What an earlier verification raised and what was built or decided since is no new finding.",
].join(' ')
/** The verify rule for this project: without a test suite (0.11.0), a missing test is no finding. */
export const verifyRule = (snap: Pick<Snapshot, 'testMode'>) => (snap.testMode === 'off' ? VERIFY_RULE.replace(', or no test proves it', '') : VERIFY_RULE)

/** How Spec Kit's CLI runs here: installed, or through uvx without installing. */
export const specifyCli = (snap: Snapshot) => (snap.tools.specify ? 'specify' : `uvx --from 'specify-cli>=1.1,<2' specify`)

/** What a spec change sets off (docs/research.de.md §5), as the constitution names it: `Persistence model: living`. */
export type Persistence = 'flow-back' | 'flow-forward' | 'living'
export function persistenceModel(constitutionMd: string | null): Persistence {
  const m = /persistence(?:\s+model)?\s*[:=-]\s*\**\s*(flow[- ]back|flow[- ]forward|living(?:\s+spec)?)/i.exec(constitutionMd ?? '')
  const value = m?.[1]?.toLowerCase().replace(' ', '-') ?? 'flow-back'
  return value.startsWith('living') ? 'living' : value === 'flow-forward' ? 'flow-forward' : 'flow-back'
}

/** What a backticked span must start with to be a command rather than a package or a tool name (`jest-expo`). */
const RUNNER = /^(?:npm|npx|pnpm|yarn|bun|bunx|deno|node|pytest|python3?|uv|poetry|cargo|go|flutter|dart|make|mvn|gradle|\.\/gradlew|dotnet|bundle|rake|rspec|mix|swift|xcodebuild|vitest|jest|phpunit|composer)(?=\s|$)/

/** The test command plan.md's `**Testing**:` line implies: a backticked command as written, else the framework's usual one. */
export function testCommandFrom(planMd: string | null): string | null {
  const line = /^\*\*Testing\*\*:\s*(.+)$/m.exec(planMd ?? '')?.[1]?.trim()
  if (!line || /NEEDS CLARIFICATION|^\[/.test(line)) return null
  const ticked = [...line.matchAll(/`([^`]+)`/g)].map(m => m[1]!.trim()).find(t => RUNNER.test(t))
  if (ticked) return ticked
  const known: [RegExp, string][] = [
    [/vitest/i, 'npx vitest run'],
    [/jest/i, 'npx jest'],
    [/playwright/i, 'npx playwright test'],
    [/pytest/i, 'pytest'],
    [/cargo/i, 'cargo test'],
    [/\bgo test|\bgo\b/i, 'go test ./...'],
    [/flutter/i, 'flutter test'],
    [/dart/i, 'dart test'],
    [/rspec/i, 'bundle exec rspec'],
    [/npm test|node:test|mocha/i, 'npm test'],
  ]
  return known.find(([re]) => re.test(line))?.[1] ?? null
}

/**
 * The project's own test script, when package.json has one: what `npm test` runs is what the project means by
 * "the tests". A watch-mode script would never end, and npm's placeholder fails on purpose: neither counts.
 */
export function testScriptCommand(packageJson: string | null, lockfiles: { pnpm: boolean; yarn: boolean; bun: boolean }): string | null {
  let script: unknown
  try {
    script = (JSON.parse(packageJson ?? '') as { scripts?: Record<string, unknown> }).scripts?.test
  } catch {
    return null
  }
  if (typeof script !== 'string' || !script.trim() || /no test specified|--watch(?:All)?\b(?!=false)/.test(script)) return null
  return lockfiles.pnpm ? 'pnpm test' : lockfiles.yarn ? 'yarn test' : lockfiles.bun ? 'bun run test' : 'npm test'
}

/** The line of a test run that says what failed (`Test Suites: 1 failed, 27 passed`), not its last words (`Ran all test suites.`). */
export function failureLine(output: string): string {
  const lines = output.split('\n').map(l => l.trim()).filter(Boolean)
  return [...lines].reverse().find(l => /\b(fail(ed|ing|ures?)?|error|✕|FAIL)\b/i.test(l)) ?? lines.at(-1) ?? ''
}

/** Whether a test run failed to start rather than failed: the shell's "command not found" and "not executable". */
export const couldNotRun = (exitCode: number, output: string) => exitCode === 126 || exitCode === 127 || /command not found|not recognized as an internal or external command/i.test(output.slice(-2000))

/** Where the spec stands with the person: approved for this text, approved for an older one, or never reviewed. */
export function specReview(snap: Snapshot, ledger: Ledger): 'approved' | 'changed' | 'unreviewed' {
  if (!snap.spec) return 'unreviewed'
  if (!ledger.approvals.spec) return 'unreviewed'
  return ledger.approvals.spec === specFingerprint(snap.spec) ? 'approved' : 'changed'
}

/** tasks.md's `##` phases in order, each with its tasks done and in all, and which one is open now. */
export type TaskPhase = { title: string; done: number; total: number }
export function taskPhases(tasks: Task[]): { phases: TaskPhase[]; current: number } {
  const phases: TaskPhase[] = []
  for (const t of tasks) {
    const title = t.phase || 'Tasks'
    let p = phases.find(x => x.title === title)
    if (!p) phases.push((p = { title, done: 0, total: 0 }))
    p.total += 1
    if (t.done) p.done += 1
  }
  return { phases, current: phases.findIndex(p => p.done < p.total) }
}

/** A phase's number as tasks.md writes it (`Phase 3: …` is 3, even with no Phase 2), else its place in the file. */
export const phaseNumber = (title: string, index: number) => Number(/^Phase\s+(\d+)/i.exec(title)?.[1] ?? index + 1)

/** `Phase 3: User Story 1 – Inspiration für den Moment (Priority: P1) 🎯 MVP` → `US1 Inspiration für den Moment (P1) MVP`. */
export function phaseLabel(title: string): string {
  return title
    .replace(/^Phase\s+\d+\s*[:.–-]\s*/i, '')
    .replace(/User Story\s+(\d+)\s*[–—:-]\s*/i, 'US$1 ')
    .replace(/\(Priority:\s*(P\d+)\)/i, '($1)')
    .replace(/🎯\s*/g, '')
    .trim()
}

/** The first `##` phase of tasks.md that still has an open task: what one implement step covers. */
export const openPhase = (tasks: Task[]) => tasks.find(t => !t.done)?.phase || null

/** A fingerprint of the task list that ignores the checkboxes: converge changes it, implement does not. */
export const tasksFingerprint = (tasks: Task[]) => fingerprint(tasks.map(t => `${t.id} ${t.text}`).join('\n'))

/** The open checklist items of a feature's `checklists/*.md`, by file. */
export function openChecklistItems(files: Record<string, string>): { file: string; open: number }[] {
  return Object.entries(files)
    .map(([file, text]) => ({ file, open: (text.match(/^\s*[-*]\s*\[ \]/gm) ?? []).length }))
    .filter(f => f.open > 0)
}

export function nextStep(snap: Snapshot, ledger: Ledger, idea: string | null = null, flow: Flow = { review: 'spec' }): Step {
  const notes: string[] = []
  const xref = snap.extensions.includes('xref')
  const has = (name: string) => (snap.commands ?? []).includes(name)
  const step = (phase: Phase, command: string | null, why: string, needsUser: string | null = null, extra: Partial<Step> = {}): Step => ({ phase, command, why, notes, needsUser, ...extra })

  // Setting Spec Kit up writes into the repository: that is always the person's call, never the autopilot's.
  if (!snap.initialized) {
    if (!snap.tools.specify && !snap.tools.uvx) {
      return step('setup', null, 'Spec Kit is not set up, and neither the specify CLI nor uvx is on this machine.', 'Install uv (https://docs.astral.sh/uv/) or the specify CLI (pipx install specify-cli).')
    }
    return snap.folder === 'empty'
      ? step('setup', `${specifyCli(snap)} ${INIT}`, 'This folder is empty: a new app, project or problem can start here with Spec Kit.', 'Tell me what you want to build (an app, a project, a problem): I set Spec Kit up for it and write the spec in your words.')
      : step('setup', `${specifyCli(snap)} ${INIT}`, 'This folder has code, but no Spec Kit yet (no .specify/).', 'Say "set up Spec Kit here" to bring this project under Spec Kit, or press Set up Spec Kit in the pane.')
  }
  if (!snap.claudeIntegration) {
    return step('integration', `${specifyCli(snap)} integration install claude`, "Spec Kit is set up, but not for Claude Code: its /speckit-* skills are missing.", 'Say "add the Claude integration", or press Add Claude integration in the pane.')
  }
  // A new project's first feature starts at the idea: researched (Validate) and shaped with the person (Shape)
  // before the constitution and the spec are written from it.
  const greenfield = snap.folder === 'empty' && snap.features.length === 0 && (!snap.featureDir || !snap.spec)
  // A PRD the person wrote first takes Validate's place: imported, reviewed, cut into features, approved as a roadmap.
  const fromPrd = !!(snap.prd || snap.prdSource)
  if (greenfield && fromPrd) {
    if (!snap.prd) {
      return step('prd', null, `A PRD is in the folder (${snap.prdSource}): it is imported to ${PRD} first.`, null, {
        prompt: `Copy ${snap.prdSource} to ${PRD} as it is, then end your turn.`,
      })
    }
    if (!snap.prdReview || !snap.roadmap?.length) return step('prd', null, 'The PRD is imported: review it and cut it into features before the spec.', null, { prompt: PRD_PROMPT })
    if (!snap.prdApproved) {
      const blocking = snap.prdReview.blocking.length
      return step('review', null, `The PRD review is written: ${snap.roadmap.length} feature${snap.roadmap.length === 1 ? '' : 's'} in the roadmap, ${blocking} open decision${blocking === 1 ? '' : 's'} block${blocking === 1 ? 's' : ''} the first.`,
        'Read the PRD review and the roadmap, then press Approve roadmap in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'prd', value: snap.prdFingerprint ?? '' } })
    }
  }
  if (greenfield && flow.validate !== false && !fromPrd) {
    const brief = snap.ideaBrief
    const decided = brief && snap.ideaDecision?.fingerprint === brief.fingerprint ? snap.ideaDecision.decision : null
    if (!brief && !idea) {
      return step('validate', null, 'No idea yet: it is researched before it becomes a spec.', 'Describe what you want to build, in your own words: I research it first, then we shape and specify it.')
    }
    if (!brief) {
      return step('validate', null, 'The idea is known: research it before it becomes a spec.', null, { prompt: validatePrompt(idea!) })
    }
    if (decided === 'drop') return step('validate', null, `You dropped the idea "${brief.title}".`, 'You dropped this idea: Reopen it in the pane, or start a new idea there.')
    if (decided !== 'build') {
      return step('review', null, `The idea brief is written: ${brief.oneLiner ?? brief.title}${brief.score !== null ? ` (score ${brief.score}/5, ${brief.recommendation ?? 'no recommendation'})` : ''}.`,
        'Read the idea brief, then press Build, Sharpen or Drop in the pane.', { approve: { key: 'idea', value: brief.fingerprint } })
    }
  }
  if (greenfield && flow.shape !== false && !snap.productBrief) {
    return step('shape', null, 'Before the spec: settle with the person what the first version is (scope, platforms, language, design, data).', null, { prompt: fromPrd ? PRD_SHAPE_PROMPT : SHAPE_PROMPT })
  }
  if (!snap.constitution || snap.constitution.principles.length === 0) {
    if (snap.ideaBrief || snap.productBrief) notes.push(BRIEFS_NOTE)
    if (snap.prd) notes.push(PRD_NOTE)
    return step('constitution', speckitCommand(snap, 'constitution'), 'The constitution is missing or still the template.')
  }
  if ((!snap.featureDir || !snap.spec) && snap.commits === false) {
    // Spec Kit opens a branch per feature only in a repository with a commit to branch from.
    return step('setup', null, 'The repository has no commit yet: Spec Kit opens a branch per feature only from one.', 'Make the first commit: press First commit in the pane, or ask for it.')
  }
  if (!snap.featureDir || !snap.spec) {
    if (snap.ideaBrief || snap.productBrief) notes.push(BRIEFS_NOTE)
    if (snap.prd) notes.push(PRD_NOTE)
    // With an approved roadmap the first feature is named already: the person's words are the PRD.
    const first = snap.prdApproved ? snap.roadmap?.[snap.features.length] : undefined
    if (!idea && first) return step('specify', `${speckitCommand(snap, 'specify')} ${roadmapSpecify(first)}`, `No feature yet; the roadmap names the first one: ${first.title}.`)
    return idea
      ? step('specify', `${speckitCommand(snap, 'specify')} ${idea}`, 'No feature yet; the person has said what to build.')
      : step('specify', speckitCommand(snap, 'specify'), 'No feature yet: describe what to build.', 'Describe the feature you want built; your own words become the spec.')
  }

  const spec = snap.spec
  // What the project builds besides the app (0.11.0): every step that plans or builds hears it.
  for (const note of [testsNote(snap.testMode), ciNote(snap.ciOn)]) if (note) notes.push(note)
  // The PRD ids this feature implements and its spec does not carry yet: the review, the plan and the analysis close them.
  const prdItem = snap.prdApproved ? roadmapItemOf(snap) : null
  const prdMissing = prdItem ? prdCoverage(prdItem.scope, spec).missing : []
  const prdGap = prdMissing.length ? `PRD ids of this feature the spec does not carry yet: ${prdMissing.join(', ')} (${PRD}). Cover each, or say why it belongs to a later feature.` : null
  if (snap.commits === false) notes.push('No commit yet: Spec Kit cannot branch per feature, and commit per task and the GitHub Action need commits (First commit in the pane).')
  const unclear = spec.reqs.filter(r => r.needsClarification).map(r => r.id)
  const specFp = specFingerprint(spec)
  // The one review: where the idea becomes the contract. A project planned before 0.4 counts as reviewed until its spec changes.
  const specApproved = ledger.approvals.spec ? ledger.approvals.spec === specFp : snap.hasPlan
  const gates = gatesOf(flow.review)
  if (!snap.hasPlan && unclear.length) return step('clarify', speckitCommand(snap, 'clarify'), `${unclear.join(', ')} still marked NEEDS CLARIFICATION; settle them before planning.`)
  if (gates.spec && !specApproved) {
    if (prdGap) notes.push(prdGap)
    return step('review', null, `The spec of ${snap.featureDir} is written: ${spec.reqs.filter(r => r.kind === 'FR').length} requirements, ${spec.outOfScope.length} out of scope, ${spec.assumptions.length} assumptions.`,
      'Review the spec against your words: keep or change each of Claude\'s assumptions, then press Approve spec in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'spec', value: specFp } })
  }
  if (!snap.hasPlan) {
    if (prdGap) notes.push(prdGap)
    return step('plan', speckitCommand(snap, 'plan'), 'The spec is written; plan.md is missing.')
  }
  if (gates.plan && snap.planFingerprint) {
    const planApproved = ledger.approvals.plan ? ledger.approvals.plan === snap.planFingerprint : snap.tasks.length > 0
    if (!planApproved) {
      return step('review', null, `The plan of ${snap.featureDir} is written.`, 'Review plan.md, then press Approve plan in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'plan', value: snap.planFingerprint } })
    }
  }
  // A feature people look at gets its look before its tasks: a design system and a mock per screen, then the person's eye.
  if (flow.design !== false && snap.ui && snap.tasks.length === 0) {
    if (designDue(snap.design)) {
      return step('design', null, `${snap.featureDir} has a user interface: settle its look before the tasks (DESIGN.md and a mock per screen).`, null, { prompt: designPrompt(snap) })
    }
    const design = snap.design!
    if (gates.design && designToReview(design) && ledger.approvals.design !== design.fingerprint) {
      const screens = design.screens?.length ?? 0
      return step('review', null, `The design of ${snap.featureDir} is drafted: ${screens} screen${screens === 1 ? '' : 's'}${designChangeLine(design)}.`,
        'Look at DESIGN.md and the mocks (/xref web or Mocks in the pane opens them in the browser), then press Approve design in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'design', value: design.fingerprint } })
    }
  }
  const drawn = snap.featureDir && snap.design?.screens?.length ? designNote(snap.featureDir) : null
  if (unclear.length) notes.push(`${unclear.join(', ')} still marked NEEDS CLARIFICATION (${speckitCommand(snap, 'clarify')}).`)
  if (snap.tasks.length === 0) {
    if (drawn) notes.push(drawn)
    return step('tasks', speckitCommand(snap, 'tasks'), 'The plan is written; tasks.md is missing.')
  }

  // A request beyond the spec reaches the spec before more code does; a contradiction is always the person's.
  const changes = ledger.semantic?.changes ?? []
  const contradiction = changes.find(c => c.kind === 'contradicts')
  if (contradiction) return step('revise', null, `"${contradiction.text}" contradicts the spec.`, `Your request "${contradiction.text}" contradicts the spec: keep the spec, or change it (To spec in the pane).`)
  const extension = changes.find(c => c.kind === 'extends')
  if (extension) {
    if (snap.persistence === 'flow-forward') return step('revise', null, `"${extension.text}" goes beyond the spec.`, `You asked for "${extension.text}", which the spec does not cover: fold it into the spec (To spec), or make it a task (As task).`)
    const revise = xref && has('xref-revise') ? speckitCommand(snap, 'xref.revise') : speckitCommand(snap, 'clarify')
    return step('revise', `${revise} The user asked during implementation: "${extension.text}". Fold it into the spec, new requirements under new ids.`, `"${extension.text}" goes beyond the spec; the spec follows the request (${snap.persistence ?? 'flow-back'}).`, null, { resolves: extension.text })
  }

  const report = evaluate(snap, ledger)
  if (report.level === 'red' || report.level === 'yellow') notes.push(`Drift ${report.level}: ${report.findings[0]?.text ?? ''}`)
  // The person asked to polish this feature's look (0.9.0): it holds across sessions until other work comes first.
  const polishing = !!snap.ui && (flow.next ? flow.next.kind === 'polish' : ledger.checkpoints.polishWanted === 'yes')
  const polishApproval = () =>
    step('review', null, `The design direction of ${snap.featureDir} is set${snap.polish?.direction ? `: ${snap.polish.direction.slice(0, 120)}` : ''}; the samples are built.`,
      "Look at polish.md and the samples' before and after shots (the feature's polish/ folder), then press Approve direction in the pane (or /xref approve); tell me what to change otherwise.", { approve: { key: 'polish', value: snap.polish!.fingerprint } })
  const mapped = Object.values(ledger.requirements).some(r => r.tasks.length > 0)
  const uncovered = report.uncovered.filter(id => !unclear.includes(id))
  if (uncovered.length && !mapped) {
    return step('map', xref ? speckitCommand(snap, 'xref.map') : '/xref map', `${uncovered.join(', ')} name no task yet; map requirements to tasks once.`)
  }
  const open = snap.tasks.filter(t => !t.done)
  const started = snap.tasks.some(t => t.done)
  // analyze before the first implement, and again after every change to the spec.
  if (open.length && has('analyze') && (ledger.checkpoints.analyze ? ledger.checkpoints.analyze !== specFp : !started)) {
    if (prdGap) notes.push(prdGap)
    return step('analyze', speckitCommand(snap, 'analyze'), started ? 'The spec changed since the last analysis: check spec, plan and tasks against each other.' : 'Before the first task: check spec, plan and tasks against each other.', null, { approve: { key: 'analyze', value: specFp } })
  }
  // An analysis that found something is followed through: its fixes go in before the next task does.
  if (open.length && (flow.remediate || ledger.checkpoints.remediate === 'due')) {
    return step('remediate', null, 'The analysis found inconsistencies: apply its remediation before the next task.', null, {
      prompt: [
        `Apply the remediation the last ${speckitCommand(snap, 'analyze')} proposed, in this step and without asking whether to.`,
        'Edit tasks.md, plan.md, data-model.md and spec.md where the findings point. Keep every existing id; new tasks get the next free T### in the phase they belong to, new requirements the next free FR-###. Check nothing off.',
        'Decide what the person left open and record it as an assumption. A product decision only the person can make (scope, a user-facing behaviour the spec leaves open) goes to mcp__speckit-xref__ask, with options and the stories it blocks.',
      ].join('\n'),
    })
  }
  // What earlier steps learned about the environment reaches every step that runs code.
  const runbook = runbookNote(snap.runbook)
  if (runbook && (open.length || (flow.lastTest && !flow.lastTest.ok))) notes.push(runbook)
  if (flow.lastTest && !flow.lastTest.ok) {
    if ((flow.repairs ?? 0) > MAX_REPAIRS) {
      return step('repair', null, `${gateWords(snap).still} after ${MAX_REPAIRS} repairs.`, `${gateWords(snap).still} after ${MAX_REPAIRS} attempts: look at the failure in the pane and decide how to go on.`)
    }
    if (flow.orchestrate) {
      const delegate: Delegate = { agent: IMPLEMENTER, model: routeModel('repair', flow.models ?? 'auto', { repairs: flow.repairs }), description: 'Repair the failing tests', brief: repairBrief(snap, flow.lastTest.output) }
      return step('repair', snap.testCommand, `${gateWords(snap).fails} (repair ${Math.max(1, flow.repairs ?? 0)} of ${MAX_REPAIRS}).`, null, { delegate, prompt: relayPrompt(delegate) })
    }
    return step('repair', snap.testCommand, `${gateWords(snap).fails} (repair ${Math.max(1, flow.repairs ?? 0)} of ${MAX_REPAIRS}).`, null, {
      prompt: `${gateWords(snap).fails}. Run \`${snap.testCommand}\`, find the cause and fix the code${snap.gate === 'check' ? '' : ' (not the tests, unless a test contradicts the spec)'}. Do not check off new tasks in this step.\nLast output:\n${flow.lastTest.output.slice(-1500)}`,
    })
  }
  if (open.length) {
    const checklists = snap.checklists ?? []
    const listFp = fingerprint(checklists.map(c => `${c.file}:${c.open}`).join('\n'))
    if (checklists.length && !started && ledger.approvals.checklists !== listFp) {
      return step('checklists', null, `${checklists.reduce((n, c) => n + c.open, 0)} checklist items are open (${checklists.map(c => c.file).join(', ')}).`, 'Checklist items are open: complete them, or press Proceed anyway in the pane (/xref approve).', { approve: { key: 'checklists', value: listFp } })
    }
    // A design pass is built only once the person approved its direction at the samples (0.9.0).
    if (isDesignPhase(snap.phase) && snap.polish && ledger.approvals.polish !== snap.polish.fingerprint) return polishApproval()
    // The story just built is tried as a person would, before the next phase builds on it (0.8.0).
    if (flow.userTest && snap.ui && started) {
      const { phases, current } = taskPhases(snap.tasks)
      const built = current > 0 ? phases[current - 1] : null
      if (built && /User Story\s+\d+/i.test(built.title)) {
        const key = `try:${phaseNumber(built.title, current - 1)}`
        const value = tasksFingerprint(snap.tasks.filter(t => t.phase === built.title))
        if (ledger.checkpoints[key] !== value) {
          return step('try', null, `${phaseLabel(built.title)} is built: try it as a person would before the next phase builds on it.`, null, { approve: { key, value }, ...tryStep(snap, flow, phaseLabel(built.title)) })
        }
      }
    }
    // One phase per step (Spec Kit's own advice for larger features): the budget and the stall check then measure real work.
    const phase = snap.phase
    const command = speckitCommand(snap, 'implement')
    if (drawn) notes.push(drawn)
    const ids = (phase ? open.filter(t => t.phase === phase) : open).map(t => t.id)
    const designPass = isDesignPhase(phase)
    if (flow.orchestrate && phase) {
      const phaseTasks = open.filter(t => t.phase === phase)
      const brief = [implementBrief(snap, phase, flow.lastTest ?? null), ...(designPass ? [DESIGN_PASS_RULES] : [])].join('\n')
      const delegate: Delegate = { agent: IMPLEMENTER, model: routeModel('implement', flow.models ?? 'auto', { tasks: phaseTasks, designPass }), description: `Implement ${phaseLabel(phase).slice(0, 40)}`, brief }
      return step('implement', command, `${open.length} of ${snap.tasks.length} tasks open; next ${open[0]!.id}.`, null, { delegate, prompt: relayPrompt(delegate) })
    }
    return step('implement', command, `${open.length} of ${snap.tasks.length} tasks open; next ${open[0]!.id}.`, null, {
      prompt: phase
        ? [
            `Run ${command} now through the Skill tool, scoped by its argument to one phase: "Only the phase '${phase}' (${ids.join(', ')}); stop when it is done." Carry that phase through.`,
            ...phaseBrief(snap, phase, flow.lastTest ?? null),
            ...(designPass ? [DESIGN_PASS_RULES] : []),
          ].join('\n')
        : undefined,
    })
  }
  const tasksFp = snap.tasksFingerprint || tasksFingerprint(snap.tasks)
  // A design pass changes the look, not the work: its tasks start no new converge (0.9.0).
  const workFp = snap.tasks.some(t => isDesignPhase(t.phase)) ? tasksFingerprint(snap.tasks.filter(t => !isDesignPhase(t.phase))) : tasksFp
  if (has('converge') && ledger.checkpoints.converge !== workFp) {
    // Converge rates its gaps too: only what matters becomes another round of work.
    const command = speckitCommand(snap, 'converge')
    return step('converge', command, 'Every task is checked: find the work the tasks missed.', null, {
      approve: { key: 'converge', value: workFp },
      prompt: `Run ${command} now through the Skill tool and carry it through. Append tasks only for its HIGH and MEDIUM gaps; list the LOW ones in your answer under 'Low, no task'.`,
    })
  }
  // A verification that still holds for this spec, these tasks and this tree means done: what comes next is the person's.
  const verified = verifyKey(snap, tasksFp)
  if (ledger.checkpoints.verify === verified) {
    // The roadmap changed since the person approved it: the next feature waits for their eye on it.
    if (snap.prd && snap.roadmap?.length && !snap.prdApproved && snap.prdFingerprint) {
      return step('review', null, `${snap.featureDir} is done, but the roadmap changed since you approved it.`,
        'Read the roadmap again (.specify/memory/roadmap.md), then press Approve roadmap in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'prd', value: snap.prdFingerprint } })
    }
    // Polish (0.9.0): on the person's word a design lead lifts the done feature's look to its platform's best. The
    // direction and two or three samples first, the person's yes at the samples, the rest as a design pass, then
    // reviews of fresh shots of every screen until one finds nothing (three at most).
    if (polishing) {
      if (!snap.polish) {
        return step('polish', null, `${snap.featureDir} is done: set a design direction that lifts its look to its platform's best, with two or three sample screens.`, null, { consumes: true, ...designerStep(flow, directionBrief(snap), 'Set the design direction') })
      }
      if (ledger.approvals.polish !== snap.polish.fingerprint) return polishApproval()
      const round = designRounds(snap.tasks) + 1
      if (round <= MAX_DESIGN_REVIEWS && ledger.checkpoints.polishCheck !== verified) {
        return step('polish', null, `The design pass is built: review round ${round} of ${MAX_DESIGN_REVIEWS}, fresh shots of every screen against the direction.`, null, {
          approve: { key: 'polishCheck', value: verified },
          ...designerStep(flow, critiqueBrief(snap, round), `Review the design pass (round ${round})`),
        })
      }
    }
    // A feature people use is tried as a person would before it is done: once per tree (0.8.0).
    if (flow.userTest && snap.ui && ledger.checkpoints.try !== verified) {
      return step('try', null, `${snap.featureDir} is verified: try the whole app as a person would before it counts as done.`, null, { approve: { key: 'try', value: verified }, ...tryStep(snap, flow, null) })
    }
    // A feature people use is played through before it is done: once per tree, by a driver that leaves a report.
    const accepting = flow.acceptance !== false && !!snap.ui && scenariosOf(snap.spec).length > 0
    if (accepting && ledger.checkpoints.accept !== verified) {
      return step('accept', null, `${snap.featureDir} is verified: play its ${scenariosOf(snap.spec).length} acceptance scenarios through as a person would.`, null, {
        approve: { key: 'accept', value: verified },
        prompt: acceptPrompt(snap),
      })
    }
    const next = flow.next
    // Ship: a release check first (nothing goes out), its gaps built as tasks, then the person's yes, then the release.
    // A release under way stays under way in a later session: a check for this tree that has not gone out yet, or the
    // person's Ship itself, through the readiness tasks and their rounds, until the release is handed over.
    const underWay = ledger.checkpoints.ship === verified && !(snap.release && ledger.checkpoints.released === snap.release.fingerprint)
    if (next ? next.kind === 'ship' : underWay || ledger.checkpoints.shipWanted === 'yes') {
      if (ledger.checkpoints.ship !== verified) {
        return step('ship', null, `${snap.featureDir} is done: check that the app is ready to release; nothing goes out in this step.`, null, { approve: { key: 'ship', value: verified }, prompt: shipPrompt(snap) })
      }
      const blockers = releaseBlockers(snap, ledger, flow.lastTest ?? null, gatesOf(flow.review).spec)
      if (blockers.length) {
        return step('ship', null, `The release waits: ${blockers[0]}.`, `Before the release: ${blockers.join('; ')}. Tick your part in ${RELEASE} as you do it; Check again in the pane runs the release check once more.`)
      }
      const release = snap.release!
      if (ledger.approvals.release !== release.fingerprint) {
        return step('review', null, `The release check is written: ${releaseLine(release)}.`,
          `Read ${RELEASE}. On your yes these run, once each: ${releaseRuns(release)}. Press Ship it in the pane (or /xref approve), or tell me what to change.`, { approve: { key: 'release', value: release.fingerprint } })
      }
      if (ledger.checkpoints.released !== release.fingerprint) {
        return step('release', null, `You approved the release: ${releaseLine(release)}.`, null, { approve: { key: 'released', value: release.fingerprint }, consumes: true, prompt: releasePrompt(release) })
      }
    }
    const quote = next ? `"${next.text.length > 80 ? next.text.slice(0, 79) + '…' : next.text}"` : ''
    if (next?.kind === 'feature' && snap.prd) notes.push(PRD_NOTE)
    if (next?.kind === 'feature') return step('specify', `${speckitCommand(snap, 'specify')} ${next.text}`, `${snap.featureDir} is done; the person named the next feature: ${quote}.`, null, { consumes: true })
    if (next?.kind === 'change') {
      const revise = xref && has('xref-revise') ? speckitCommand(snap, 'xref.revise') : null
      return step('revise', null, `${snap.featureDir} is done; the person asks for a change: ${quote}.`, null, { consumes: true, prompt: changePrompt(snap, next.text, revise) })
    }
    if (next?.kind === 'bug') {
      if (runbook) notes.push(runbook)
      return step('bug', null, `A bug in ${snap.featureDir}: ${quote}.`, null, { consumes: true, prompt: bugPrompt(snap, next.text, name => speckitCommand(snap, name), has) })
    }
    // A roadmap names the next feature, and the gate before it is the person's part.
    const upcoming = snap.prdApproved ? snap.roadmap?.[snap.features.length] : undefined
    const roadmapAsk = upcoming && !flow.nextKind ? ` Next in the roadmap: "${upcoming.title}"${upcoming.gate ? `, after the gate ${upcoming.gate} (your part)` : ''}; press Next from roadmap when it is time.` : ''
    return step('done', null, `${snap.featureDir} is done: every task is checked, converged and verified.`, doneAsk(flow.nextKind) + roadmapAsk)
  }
  // Verify can always find one more thing: after two rounds in a run (three with acceptance and its fixes), closing the
  // feature is the person's call. One counter for both, so the acceptance rounds are not cut short.
  const accepting = (flow.acceptance !== false && !!snap.ui && scenariosOf(snap.spec).length > 0) || (!!flow.userTest && !!snap.ui)
  // A design pass brings its own verify rounds: one after the pass, one after each review that found something.
  const rounds = (accepting ? MAX_ACCEPTS : MAX_VERIFIES) + (polishing ? MAX_DESIGN_REVIEWS + 1 : 0)
  if ((flow.verifies ?? 0) >= rounds) {
    return step('review', null, accepting ? `Verify and acceptance found new work in each of their last ${rounds} rounds, and it is built.` : `Verify found new work in each of its last ${rounds} rounds, and it is built.`,
      `Look at what the last ${accepting ? 'verifications and acceptance runs' : 'verifications'} added: press Call it done in the pane (or /xref approve) to close the feature as it is, or Resume for one more round.`, { approve: { key: 'done', value: verified } })
  }
  if (xref) {
    const command = speckitCommand(snap, 'xref.check')
    return step('verify', command, 'Every task is checked: check the code against the spec.', null, {
      approve: { key: 'verify', value: verified },
      prompt: `Run ${command} now through the Skill tool and carry it through. ${verifyRule(snap)}`,
    })
  }
  // Without the extension there is no command the model can run: it checks by itself, and the mod's intent check follows.
  return step('verify', null, 'Every task is checked: check the code against the spec.', null, {
    approve: { key: 'verify', value: verified },
    prompt: [
      "Check the code against the spec and against the person's own words (the spec's Input), by yourself: /xref check is the person's command, not one you can run.",
      'For each requirement name the code and the test that prove it. For each point the person made, say whether the app does it.',
      verifyRule(snap),
      "Each HIGH or MEDIUM finding becomes a new task at the end of tasks.md under '## Phase N: Verification' (the next free T### ids). Then end your turn.",
    ].join('\n'),
  })
}

/** A user test step: relayed to the tester subagent when orchestrated, else carried out in the main session. */
function tryStep(snap: Snapshot, flow: Flow, story: string | null): Pick<Step, 'delegate' | 'prompt'> {
  const brief = tryBrief(snap, { story })
  if (!flow.orchestrate) return { prompt: [TESTER_PROMPT, brief].join('\n') }
  const delegate: Delegate = { agent: TESTER, model: routeModel('try', flow.models ?? 'auto'), description: story ? `Try ${story.slice(0, 40)}` : 'Try the whole app', brief }
  return { delegate, prompt: relayPrompt(delegate) }
}

/** A design lead's step (0.9.0): relayed to the designer subagent when orchestrated, else carried out in the main session. */
function designerStep(flow: Flow, brief: string, description: string): Pick<Step, 'delegate' | 'prompt'> {
  if (!flow.orchestrate) return { prompt: [DESIGNER_PROMPT, brief].join('\n\n') }
  const delegate: Delegate = { agent: DESIGNER, model: routeModel('design', flow.models ?? 'auto'), description, brief }
  return { delegate, prompt: relayPrompt(delegate) }
}

/** What Validate is handed: the person's words and the skill that researches them. */
export function validatePrompt(idea: string): string {
  return [
    'Validate the idea before it becomes a spec, with the speckit-xref:validate skill: research it (the speckit-xref:idea-researcher agent does the web research where web tools are there) and write .specify/memory/idea-brief.md in the format the skill gives.',
    `The idea, in the person's words: "${idea}"`,
    'Never invent a source: an alternative without a URL you fetched is marked (unverified). Without web tools, say so in the brief. Do not write a **Decision** line: Build, Sharpen or Drop is the person\'s call.',
  ].join('\n')
}

const SHAPE_PROMPT = [
  'Shape the first version with the person before the spec is written, with the speckit-xref:shape skill.',
  'Ask in the AskUserQuestion dialog only what the idea and .specify/memory/idea-brief.md leave open: which user stories make the first version (the MVP cut), platforms, language and internationalisation, the design direction (mood, references, dark mode, accessibility), data and accounts. At most 4 questions a round, the recommended answer first.',
  "Write .specify/memory/product-brief.md with '## Decisions (the person's)' and '## Assumptions (Claude's)'. Where nobody can answer (no dialog), record each point as an assumption.",
].join('\n')

const BRIEFS_NOTE =
  "Use .specify/memory/idea-brief.md and .specify/memory/product-brief.md: the decisions in them are the person's (write them as decided, never as assumptions), the brief's success measures become SC-###, its riskiest assumption is what the first user story tests, and its differentiation belongs in the constitution."

/** Reads an idea brief (`.specify/memory/idea-brief.md`, the format the validate skill writes). */
export function parseIdeaBrief(markdown: string): IdeaBrief {
  const field = (name: string) => new RegExp(`^\\*\\*${name}\\*\\*:\\s*(.+)$`, 'mi').exec(markdown)?.[1]?.trim() ?? null
  const section = (name: RegExp) => {
    const out: string[] = []
    let inside = false
    for (const line of markdown.split('\n')) {
      const h = /^##\s+(.+)$/.exec(line)
      if (h) {
        inside = name.test(h[1] ?? '')
        continue
      }
      const item = inside ? /^\s*(?:[-*]|\d+\.)\s+(.+)$/.exec(line) : null
      if (item) out.push(item[1]!.trim())
    }
    return out
  }
  const rec = field('Recommendation')?.toLowerCase().match(/build|sharpen|drop/)?.[0] as IdeaBrief['recommendation'] | undefined
  const score = Number(/([\d.]+)\s*\/\s*5/.exec(field('Score') ?? '')?.[1])
  const research = field('Research')
  return {
    title: /^#\s+(?:Idea Brief:\s*)?(.+)$/m.exec(markdown)?.[1]?.trim() ?? 'Idea',
    oneLiner: field('One-liner'),
    recommendation: rec ?? null,
    score: Number.isFinite(score) ? score : null,
    research: !!research && !/^none\b/i.test(research),
    alternatives: section(/^alternatives/i).map(line => {
      const link = /^\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)\s*[:–—-]?\s*(.*)$/.exec(line)
      if (link && !/\(unverified\)/i.test(line)) return { name: link[1]!, url: link[2]!, note: link[3] ?? '', verified: true }
      const [name, ...rest] = line.replace(/\[([^\]]+)\]\([^)]*\)/, '$1').split(/:\s+/)
      return { name: name!.replace(/\s*\(unverified\)\s*/i, '').trim(), url: null, note: rest.join(': '), verified: false }
    }),
    risks: section(/riskiest/i),
    kill: section(/^kill/i),
    success: section(/^success/i),
    fingerprint: fingerprint(markdown.split('\n').filter(l => !/^\*\*Decision\*\*:/i.test(l)).join('\n')),
  }
}

/** The step as one line, as the pane, /xref and the note on each prompt show it. */
export const stepLine = (s: Step) => (s.command ? `${s.command} · ${s.why}` : s.why)

export const idleAutopilot = (): Autopilot => ({
  on: false,
  paused: null,
  steps: 0,
  max: 25,
  last: null,
  stalls: 0,
  lastPhase: null,
  idea: null,
  repairs: 0,
  lastTest: null,
  startedAt: null,
  costAtStart: 0,
  night: false,
  scope: null,
  remediate: false,
  remediations: 0,
  testNote: null,
  next: null,
  nextKind: null,
  verifies: 0,
  acceptBaseline: null,
  releaseRows: null,
  delegation: null,
})

/** Whether the person's next words are the idea to specify: the autopilot waits on them for exactly that. */
export const takesIdea = (step: Step, snap: Snapshot) =>
  step.phase === 'specify' || (step.phase === 'validate' && step.needsUser !== null && !snap.ideaBrief) || (step.phase === 'setup' && snap.folder === 'empty' && step.command !== null)

/** What the model reads beside the person's prompt while the autopilot waits before Spec Kit is there. */
export function setupNote(step: Step, snap: Snapshot): string {
  const lines = [`speckit-xref · autopilot waiting · ${step.why}`]
  if (step.phase === 'setup' && step.command && snap.folder === 'empty') {
    lines.push(`If this message says what to build, set Spec Kit up now with the speckit-xref:speckit skill (\`${step.command}\`); the autopilot then goes on with the constitution and the spec in the person's words.`)
  } else if (step.phase === 'setup' && step.command) {
    lines.push(`Set Spec Kit up (speckit-xref:speckit skill, \`${step.command}\`) only if this message asks for it; otherwise leave the repository as it is.`)
  } else if (step.phase === 'integration') {
    lines.push(`Run \`${step.command}\` only if this message asks for it.`)
  }
  return lines.join('\n')
}

/** What has to change between two autopilot steps for the run to count as moving. */
export function progressKey(snap: Snapshot, ledger: Ledger): string {
  const report = evaluate(snap, ledger)
  const mapped = Object.values(ledger.requirements).filter(r => r.tasks.length > 0).length
  return [
    snap.initialized,
    snap.claudeIntegration,
    snap.constitution?.principles.length ?? 0,
    snap.featureDir ?? '-',
    snap.spec?.reqs.length ?? 0,
    snap.spec?.reqs.filter(r => r.needsClarification).length ?? 0,
    snap.hasPlan,
    !!snap.ideaBrief,
    !!snap.productBrief,
    snap.design ? `${snap.design.system}:${snap.design.screens?.length ?? '-'}` : '-',
    `${report.done}/${report.tasks}`,
    snap.tasksFingerprint ?? '-',
    mapped,
    report.level,
    Object.values(report.levels).join('/'),
    ledger.semantic?.at ?? '-',
    JSON.stringify(ledger.checkpoints),
  ].join('|')
}

/** The rules the autopilot gives the model with every step it hands over. */
export const AUTONOMY_RULES = [
  'Autopilot is on. Carry the step through without asking whether to continue: when you end your turn, the autopilot moves on by itself.',
  'Decide what the person left open, from the spec, the constitution and the repository, and record those choices as assumptions in the artifact you write.',
  "When you get past a problem of the project's environment (a port, a flag, a device's or simulator's quirk, the name of an OS permission), add one line on it to .specify/memory/runbook.md, so later steps start from it; what this session's tool permissions allow is no such problem. When you commit, commit the feature's xref.json with it.",
  'Stop only for what only the person can decide: the product idea, a [NEEDS CLARIFICATION] question, a conflict between their request and the spec, anything destructive or irreversible, credentials or payments. Then call mcp__speckit-xref__ask with the question (and the user stories it blocks, if any); if it answers with the person\'s choice, go on with it, otherwise put the question in your answer and end your turn.',
]

/** The prompt the autopilot submits for one step. */
export function autopilotPrompt(step: Step, n: number, max: number, context: string | null): string {
  return [
    `[speckit-xref autopilot · step ${n}/${max}] ${step.phase}: ${step.why}`,
    step.prompt ?? `Run ${step.command} now: invoke it through the Skill tool and carry it through.`,
    ...step.notes.map(note => `Note: ${note}`),
    '',
    ...AUTONOMY_RULES,
    ...(context ? ['', context] : []),
  ].join('\n')
}

/** Whether a model's answer ends on a question, the one case the autopilot asks a small model about. */
export const endsWithQuestion = (answer: string) => /\?["')\]*_\s]*$/.test(answer.trim().slice(-400))

/** The labels for that question; the first means stop. A "shall I continue?" is the second. */
export const QUESTION_LABELS = ['needs a decision only the person can make', 'asks only whether to continue, or reports progress'] as const

/** The phase strip: `✓setup ✓const ✓spec ✓plan ✓tasks ▶impl 7/8 ·verify`; `◌spec` is a spec passed without your review. */
export function phaseStrip(snap: Snapshot, step: Step, unreviewed = false): string {
  // The idea column shows only for a project that started at an idea (Validate, Shape).
  const ideas = !!snap.ideaBrief || !!snap.productBrief || !!snap.prd || step.phase === 'validate' || step.phase === 'shape' || step.phase === 'prd'
  // The design column shows for a feature with screens, and while its design is drawn or reviewed.
  const drawn = !!snap.design?.screens?.length || step.phase === 'design' || step.approve?.key === 'design'
  // The ship column shows once a release was checked, and while it is.
  const shipping = !!snap.release || step.phase === 'ship' || step.phase === 'release' || step.approve?.key === 'release'
  // The polish column shows once a design direction is set, and while it is.
  const polished = !!snap.polish || step.phase === 'polish' || step.approve?.key === 'polish'
  const order: [string, Phase[]][] = [
    ['setup', ['setup', 'integration']],
    ...(ideas ? [['idea', ['prd', 'validate', 'shape']] as [string, Phase[]]] : []),
    ['const', ['constitution']],
    ['spec', ['specify', 'clarify', 'review', 'revise']],
    ['plan', ['plan']],
    ...(drawn ? [['design', ['design']] as [string, Phase[]]] : []),
    ['tasks', ['tasks', 'map', 'analyze', 'remediate', 'checklists']],
    ['impl', ['implement', 'repair', 'rework', 'adjust', 'converge', 'bug']],
    ['verify', ['verify', 'accept', 'try']],
    ...(polished ? [['polish', ['polish']] as [string, Phase[]]] : []),
    ...(shipping ? [['ship', ['ship', 'release']] as [string, Phase[]]] : []),
  ]
  // A review sits in the column of what it reviews.
  const reviewed: Record<string, Phase> = { idea: 'validate', prd: 'prd', plan: 'plan', design: 'design', done: 'verify', release: 'ship', polish: 'polish' }
  const phase = step.phase === 'review' && step.approve ? (reviewed[step.approve.key] ?? 'review') : step.phase
  // Done: every column is behind it.
  const at = phase === 'done' ? order.length : order.findIndex(([, phases]) => phases.includes(phase))
  const done = snap.tasks.filter(t => t.done).length
  return order
    .map(([label], i) => {
      const extra = label === 'impl' && snap.tasks.length ? ` ${done}/${snap.tasks.length}` : ''
      return i < at ? `${label === 'spec' && unreviewed ? '◌' : '✓'}${label}` : i === at ? `▶${label}${extra}` : `·${label}`
    })
    .join(' ')
}

